function loadProgress(){const key=progressKey();if(!key)return;try{const stored=JSON.parse(localStorage.getItem(key)||'{}');Object.assign(state,{completed:stored.completed||0,errorSolved:stored.errorSolved||false,answerText:stored.answerText||''});}catch{}}
loadProgress();
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function save(){const key=progressKey();if(!key)return;localStorage.setItem(key,JSON.stringify({completed:state.completed,errorSolved:state.errorSolved,answerText:state.answerText}))}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2400)}
function link(source,label='Kaynağı aç'){return `<a href="${source.url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`}
function heading(eyebrow,title,desc,right=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`}
const guestLocale=()=>window.realdevLocale==='en'?'en':'tr';
const bilingual=(tr,en)=>guestLocale()==='en'?en:tr;
function publicConcepts(){const bank=window.realdevContentBank||{cards:[],sources:{}};return [...concepts,...expandedConcepts,...bank.cards.map(x=>({...x,source:{label:bank.sources[x.source]?.name||x.source,url:bank.sources[x.source]?.url||'#'}}))].slice(0,10);}
function publicLanding(){const en=guestLocale()==='en';return `<section class="public-hero"><div class="eyebrow">REALDEVELOPER · DEVELOPER PRACTICE STUDIO</div><h1>${en?'Build confidence by explaining the code you use.':'Kullandığın kodu açıklayarak gerçek becerini geliştir.'}</h1><p>${en?'A guided practice space for developers: read code, diagnose realistic errors, explain technical concepts, and build a learning path from evidence.':'Yazılımcılar için uygulamalı çalışma alanı: kodu oku, gerçekçi hataları teşhis et, teknik kavramları açıkla ve kanıta dayalı bir öğrenme rotası oluştur.'}</p><div class="public-hero-actions"><a class="primary-button" href="/auth.html#/sign-up">${en?'Create a free account':'Ücretsiz hesap oluştur'} →</a><a class="secondary-button" href="/demo/questions" data-public-view="demoQuiz">${en?'Try sample questions':'Örnek soruları dene'}</a></div><div class="public-note">${en?'Explore the public samples without an account. Sign in to save answers, notes and your personal progress.':'Örnekleri hesapsız incele. Cevaplarını, notlarını ve kişisel ilerlemeni kaydetmek için giriş yap.'}</div></section><section class="public-section"><div><div class="eyebrow">${en?'WHAT YOU CAN PRACTICE':'NELER ÇALIŞABİLİRSİN'}</div><h2>${en?'Practice the work, not just the vocabulary.':'Sadece kavramı değil, yazılım işini çalış.'}</h2></div><div class="public-feature-grid"><article><span>01 · ${en?'REASON':'AKIL YÜRÜT'}</span><h3>${en?'Read and write code':'Kod oku ve yaz'}</h3><p>${en?'Predict behavior, run focused exercises, and explain decisions in your own words.':'Kod davranışını tahmin et, odaklı görevleri çöz ve kararlarını kendi cümlelerinle açıkla.'}</p></article><article><span>02 · ${en?'DEBUG':'HATA AYIKLA'}</span><h3>${en?'Learn from real errors':'Gerçek hatalardan öğren'}</h3><p>${en?'Practice safe Git, API, IDE, .NET and Unity troubleshooting with visible evidence.':'Git, API, IDE, .NET ve Unity hatalarını kanıta bakarak güvenli biçimde teşhis et.'}</p></article><article><span>03 · ${en?'GROW':'GELİŞ'}</span><h3>${en?'Follow your own route':'Kendi rotanı izle'}</h3><p>${en?'After sign-in, your profile, notes, answer history, skill map and study route stay tied to your account.':'Girişten sonra profilin, notların, cevap geçmişin, beceri haritan ve çalışma rotan hesabına bağlı tutulur.'}</p></article></div></section><section class="public-section public-samples"><div><div class="eyebrow">${en?'OPEN PREVIEW':'AÇIK ÖNİZLEME'}</div><h2>${en?'Try a small sample':'Küçük bir örnek dene'}</h2><p>${en?'Guests can answer two sample questions in each preview topic and browse ten sourced concept cards. Guest answers are temporary and are never saved.':'Misafirler her örnek konu başlığında iki soruyu çözebilir ve kaynaklı on kavram kartını inceleyebilir. Misafir cevapları geçicidir, kaydedilmez.'}</p></div><div class="public-sample-actions"><a class="secondary-button" href="/demo/questions" data-public-view="demoQuiz">${en?'Open sample questions':'Örnek testleri aç'} →</a><a class="secondary-button" href="/demo/concepts" data-public-view="demoConcepts">${en?'Browse 10 concepts':'10 kavrama göz at'} →</a></div></section><section class="public-bottom"><h2>${en?'Your learning history starts after sign-in.':'Kişisel çalışma geçmişin giriş yaptıktan sonra başlar.'}</h2><p>${en?'Create an account to unlock the complete skill assessment, code lab, interview projects, saved notes and personalized study route.':'Tam beceri taramasını, kod alanını, mülakat projelerini, kayıtlı notlarını ve kişisel çalışma rotanı açmak için hesap oluştur.'}</p><a class="primary-button" href="/auth.html#/sign-up">${en?'Sign up / sign in':'Kayıt ol / giriş yap'} →</a></section>`;}
function guestQuizView(){const en=guestLocale()==='en';const q=guestQuestions[guestQuizIndex];if(!q)return `<section class="public-demo-card"><div class="eyebrow">${en?'SAMPLE COMPLETE':'ÖRNEK TAMAMLANDI'}</div><h1>${en?'That was the preview.':'Örnek tur tamamlandı.'}</h1><p>${en?'Your guest answers were only held temporarily and were not saved. Sign in to keep a learning history and unlock the full practice library.':'Misafir cevapların geçici olarak tutuldu, kaydedilmedi. Cevap geçmişini saklamak ve tüm çalışma kütüphanesini açmak için giriş yap.'}</p><div class="public-hero-actions"><a class="primary-button" href="/auth.html#/sign-up">${en?'Create an account':'Hesap oluştur'} →</a><button class="secondary-button" data-public-view="landing">${en?'Back to home':'Ana sayfaya dön'}</button></div></section>`;return `<section class="public-demo-card"><button class="text-button" data-public-view="landing">← ${en?'Public home':'Tanıtım sayfası'}</button><div class="quiz-top"><span class="eyebrow">${q.area[en?1:0]}</span><span class="quiz-step">${guestQuizIndex+1} / ${guestQuestions.length}</span></div><div class="progress"><span style="width:${(guestQuizIndex+1)/guestQuestions.length*100}%"></span></div><h1 class="quiz-question">${q.q[en?1:0]}</h1><div class="choice-list">${q.options.map((option,index)=>`<button class="choice ${guestAnswered&&guestSelected===index?'selected':''}" data-guest-choice="${index}" ${guestAnswered?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+index)}</span><span>${option[en?1:0]}</span></button>`).join('')}</div>${guestAnswered?`<div class="result-box ${guestSelected===q.answer?'':'warning'}"><h4>${guestSelected===q.answer?(en?'Good catch.':'İyi yakaladın.'):(en?'Review this one.':'Bu soruyu tekrar incele.')}</h4>${q.why[en?1:0]}<div style="margin-top:8px;font-size:10px">${link(q.source,en?'Reference':'Kaynak')}</div></div>`:''}<div class="quiz-actions"><span class="text-muted">${en?'Guest answers are not saved.':'Misafir cevapları kaydedilmez.'}</span>${guestAnswered?`<button class="primary-button" data-guest-action="next">${guestQuizIndex===guestQuestions.length-1?(en?'Finish':'Bitir'):(en?'Next':'Sonraki')} →</button>`:''}</div></section>`;}
function guestConceptsView(){const en=guestLocale()==='en',cards=publicConcepts(),selected=cards.find(x=>x.id===guestConceptOpen);const value=x=>typeof x==='string'?x:(x?.[en?'en':'tr']||x?.tr||'');const name=x=>value(x.name||x.title);const desc=x=>value(x.desc||x.description);const body=x=>value(x.body||x.explanation||x.desc);return `<section class="public-demo-card"><button class="text-button" data-public-view="landing">← ${en?'Public home':'Tanıtım sayfası'}</button><div class="eyebrow">${en?'10 OPEN CONCEPTS':'AÇIK 10 KAVRAM'}</div><h1>${en?'A small glossary to start with.':'Başlangıç için kısa bir kavram kütüphanesi.'}</h1><p>${en?'Read sourced explanations and follow the original references. Personal notes and the full library are available after sign-in.':'Kaynaklı açıklamaları ve özgün referansları incele. Kişisel notlar ve tam kütüphane girişten sonra açılır.'}</p><div class="concept-grid">${cards.map(x=>`<a class="concept-card" href="#concept-${encodeURIComponent(x.id)}" data-guest-concept="${esc(x.id)}"><span class="concept-type">${esc(value(x.type)|| (en?'Concept':'Kavram'))}</span><h3>${esc(name(x))}</h3><p>${esc(desc(x))}</p><div class="concept-footer"><span>${en?'Sourced':'Kaynaklı'}</span><span>${en?'Read':'İncele'} →</span></div></a>`).join('')}</div>${selected?`<article class="concept-detail"><div class="eyebrow">${esc(value(selected.type))}</div><h2>${esc(name(selected))}</h2><div class="concept-body">${esc(body(selected)).replace(/\n/g,'<br>')}</div>${selected.analogy?`<div class="analogy"><strong>${en?'Example:':'Örnek:'}</strong> ${esc(value(selected.analogy))}</div>`:''}${selected.source?.url&&selected.source.url!=='#'?`<div class="source-note" style="margin-top:13px"><strong>${en?'Reference':'Kaynak'}:</strong> ${link(selected.source,esc(selected.source.label||'Reference'))}</div>`:''}</article>`:''}<div class="public-note">${en?'Sign in to add notes, revisit concepts and save learning gaps.':'Not eklemek, kavramlara sonra dönmek ve eksiklerini kaydetmek için giriş yap.'} <a href="/auth.html#/sign-up">${en?'Create an account':'Hesap oluştur'} →</a></div></section>`;}
function today(){const progress=Math.min(100,Math.round(state.completed/4*100));return `<div class="welcome-row"><div><h1>Merhaba, geliştirici</h1><p>Bugün küçük bir adım atalım. Önce düşün, sonra dene, en son açıkla.</p></div><div class="streak">✦ <strong>${state.completed}</strong> çalışma tamamlandı</div></div>
<section class="hero-card"><div class="hero-content"><div class="hero-overline"><span class="live-dot"></span> BUGÜNÜN ÇALIŞMASI · 15 DK</div><h2>Kodu yalnızca çalıştırma. Ne yaptığını da bil.</h2><p>React’te state güncellemesini tahmin et, ardından C# runtime’ının rolünü kendi cümlelerinle anlat.</p><div class="hero-meta"><span>◉ Kod okuma</span><span>↗ Kavram açıklama</span><span>◷ 4 kısa adım</span></div></div><button class="primary-button" data-action="start-quiz">Çalışmaya başla <span>→</span></button></section>
<div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Bugünkü rota</h2><button class="subtle-link" data-view="map">Tüm beceriler →</button></div><div class="task-list"><div class="task-row" data-action="start-quiz"><span class="task-icon purple">⌘</span><span class="task-copy"><strong>Kod davranışını tahmin et</strong><small>React · state ve yeniden render</small></span><span class="task-time">4 dk</span><span class="task-arrow">›</span></div><div class="task-row" data-view="errors"><span class="task-icon orange">⌁</span><span class="task-copy"><strong>Bir Git hatasını çöz</strong><small>non-fast-forward · güvenli inceleme</small></span><span class="task-time">5 dk</span><span class="task-arrow">›</span></div><div class="task-row" data-view="concepts"><span class="task-icon blue">▤</span><span class="task-copy"><strong>Bir kavramı kendi cümlenle açıkla</strong><small>C# · Common Language Runtime</small></span><span class="task-time">3 dk</span><span class="task-arrow">›</span></div></div><div class="panel-foot"><span>İlerleme bu cihazda kaydedilir</span><span>${progress}% rota</span></div></section>
<section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Beceri haritandan</h2><span class="eyebrow">KEŞİF AŞAMASI</span></div><div class="skill-list"><div class="skill-row"><span class="skill-name">React · kod okuma</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill" style="width:0"></div></div></div><div class="skill-row"><span class="skill-name">C# · .NET temelleri</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill warm" style="width:0"></div></div></div><div class="skill-row"><span class="skill-name">Git · hata çözme</span><span class="skill-state">${state.errorSolved?'bir görev tamamlandı':'ölçülmedi'}</span><div class="skill-track"><div class="skill-fill" style="width:${state.errorSolved?25:0}%"></div></div></div><div class="skill-row"><span class="skill-name">Unity · C#</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill warm" style="width:0"></div></div></div></div><div class="panel-foot"><span>İlk kısa tarama ile başlangıç seviyesi oluşur.</span></div></section></div>
<div class="tip-card"><span class="tip-spark">✳</span><div><strong>Çalışma ipucu</strong><p>AI’ın ürettiği bir kodu kullanmadan önce kendine sor: Girdi ne? Çıktı ne? Hata olursa ilk hangi kanıta bakarım?</p></div></div>
<div class="section-label">Güncel gelişmeler</div><div class="news-inline">${news.slice(0,2).map((n,i)=>`<article class="news-mini"><div class="source-line"><span>${n.date} · ${n.tag}</span><span class="source-badge">${n.kind}</span></div><h3>${n.title}</h3><p>${n.body}</p><button class="text-button" data-view="news">Haberleri gör →</button></article>`).join('')}</div>`}
function quizView(){if(!state.quizMode)return `${heading('BECERİ TARAMASI','Neleri gerçekten anladığını keşfet','Kısa görevler kod okuma, hata teşhisi ve teknik anlatım pratiği sunar. “Bilmiyorum” demek de geçerli bir başlangıçtır.',`<span class="day-pill">10–15 dakika</span>`)}<section class="quiz-card"><p class="quiz-context">Önce kendin dene, sonra açıklamayı ve kaynağı incele.</p><button class="primary-button" data-action="start-quiz">Tarama görevlerine başla <span>→</span></button></section>`;return quizCard()}function quizCard(){const q=quiz[state.quizIndex];if(!q)return `<section class="quiz-card"><div class="eyebrow">TARAMA TAMAMLANDI</div><h2 class="quiz-question" style="margin-top:10px">İlk keşif turu bitti.</h2><p class="quiz-context">${state.completed} kısa görev tamamladın. Bu ilk tur yalnızca başlangıç sinyali; daha doğru beceri haritası için düzenli pratikte farklı örnekler de çözeceğiz.</p><button class="primary-button" data-action="reset-quiz">Bir tur daha yap <span>→</span></button> <button class="secondary-button" data-view="today">Bugüne dön</button></section>`;return `<section class="quiz-card"><div class="quiz-top"><span class="eyebrow">BAŞLANGIÇ TARAMASI · ${q.area}</span><span class="quiz-step">${state.quizIndex+1} / ${quiz.length}</span></div><div class="progress"><span style="width:${(state.quizIndex+1)/quiz.length*100}%"></span></div><h2 class="quiz-question">${q.question}</h2><p class="quiz-context">${q.context}</p>${q.code?`<div class="code-block">${esc(q.code)}</div>`:''}<div class="choice-list" style="margin-top:${q.code?'15px':'0'}">${q.options.map((o,i)=>`<button class="choice ${state.selected===i?'selected':''}" data-choice="${i}" ${state.answered?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${o}</span></button>`).join('')}</div>${state.answered?`<div class="result-box ${state.selected===q.answer?'':'warning'}"><h4>${state.selected===q.answer?'İyi yakaladın.':'Burada tekrar düşünmeye değer.'}</h4>${q.explain}<div style="margin-top:8px;font-size:10px">${link(q.source,'Bilgiyi doğrula')}</div></div>`:''}<div class="quiz-actions"><span class="text-muted">${state.answered?'Cevabın ve açıklama kaydedildi.':'Emin değilsen “Şimdilik bilmiyorum” diyebilirsin.'}</span>${state.answered?`<button class="primary-button" data-action="next-quiz">${state.quizIndex===quiz.length-1?'Tamamla':'Sonraki'} <span>→</span></button>`:`<button class="secondary-button" data-action="dont-know">Şimdilik bilmiyorum</button>`}</div></section>`}
function mapView(){return `${heading('GELİŞİMİN','Beceri haritam','Bu ilk prototipte görev cevapları cihazında saklanır. Alanlar görevlerle zaman içinde keşfedilir; henüz değerlendirilmemiş beceriye seviye atamayız.')}<div class="two-col"><section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Çalışma alanları</h2><span class="eyebrow">HEDEF: GENEL EKSİKLERİ KAPAT</span></div><div class="skill-list">${[['Frontend','JavaScript · TypeScript · React'],['Backend','Java · Python · C# / .NET'],['Veritabanı','SQL · veri modeli · DDL'],['Git ve ekip çalışması','branch · merge · pull request'],['Test ve kalite','unit · integration · debug'],['DevOps ve cloud','CI/CD · AWS temelleri'],['Unity ve mobil oyun','C# · oyun döngüsü · build'],['AI ile üretim','kod açıklama · doğrulama']].map(x=>`<div class="task-row"><span class="task-icon purple">◇</span><span class="task-copy"><strong>${x[0]}</strong><small>${x[1]}</small></span><span class="chip">Henüz ölçülmedi</span></div>`).join('')}</div></section><aside class="panel panel-pad"><h2 class="panel-title">Ölçüm nasıl işler?</h2><p class="quiz-context" style="margin-top:12px">Bir doğru cevap tek başına “uzman” anlamına gelmez. Kod yazma, açıklama, hata ayıklama ve yeni senaryoya aktarım farklı görevlerle gözlemlenir.</p><div class="error-steps"><div class="error-step"><span class="number">1</span><div><strong>Önce bağımsız dene</strong><p>İpucu almadan ne yapabildiğin görünür.</p></div></div><div class="error-step"><span class="number">2</span><div><strong>Gerekince ipucu al</strong><p>Hangi yardımın gerektiği de ilerlemeni açıklar.</p></div></div><div class="error-step"><span class="number">3</span><div><strong>Başka örnekte tekrar et</strong><p>Bilgiyi yeni duruma uygulamanı kontrol ederiz.</p></div></div></div><button class="primary-button" style="margin-top:16px" data-action="start-quiz">Kısa taramayı başlat <span>→</span></button></aside></div>`}
function errorsView(){return `${heading('HATA LABORATUVARI','Hata mesajını okuyup çözüm yolunu bul','Gerçekçi çıktıları incele: mesaj ne söylüyor, neyi henüz bilmiyorsun ve hangi kanıtı toplarsın?')}<div class="two-col"><section class="feature-card"><div class="eyebrow">GIT · PUSH HATASI · BAŞLANGIÇ</div><h2 class="quiz-question" style="margin-top:10px">Uzak branch ileride görünüyor</h2><div class="error-meta"><span class="chip red">non-fast-forward</span><span class="chip">Git</span><span class="chip">Güvenli teşhis</span></div><div class="code-block">! [rejected] main -&gt; main (non-fast-forward)\nerror: failed to push some refs\nhint: Updates were rejected because the tip of your current branch is behind its remote counterpart.</div><p class="quiz-context" style="margin-top:15px">Şu an <code>main</code> branch’indesin. Ekip arkadaşın uzak branch’e commit gönderdi; sende henüz fetch edilmemiş. İlk ne yaparsın?</p><textarea id="errorAnswer" class="answer-area" placeholder="Önce şunu kontrol ederim… çünkü…">${esc(state.answerText)}</textarea><div class="answer-tools"><button class="mic-button" data-action="mic">🎙 Sesli açıkla</button><button class="primary-button" data-action="check-error">Yanıtımı kaydet <span>→</span></button><button class="subtle-link" data-action="hint">İpucu ${state.errorHint?'gösterildi':''}</button></div>${state.errorHint?`<div class="result-box" style="margin-top:13px"><h4>İpucu</h4>Önce yerel çalışma ağacını ve branch’in uzakla ilişkisini incele. <code>git fetch</code> uzak bilgileri indirir ama dosyalarını birleştirmez. Ardından commit farkını görüp ekip akışına uygun merge veya rebase planla.</div>`:''}${state.errorSolved?`<div class="result-box"><h4>Yanıtın bu cihazda saklandı; otomatik doğruluk puanı yok.</h4>${/--force|push\s+-f/i.test(state.answerText)?'Force push paylaşılan geçmişi değiştirebilir; ekip akışını ve remote geçmişini incelemeden kullanma.':'Güvenli bir teşhis yolu; önce git status/git fetch ile uzak farkı incele, sonra ekip akışına uygun merge veya rebase seç, test et ve pushla.'} ${link(sources.git,'Git merge dokümanı')}</div>`:''}</section><aside class="panel panel-pad"><h2 class="panel-title">Hata ayıklama sırası</h2><p class="quiz-context" style="margin:8px 0 17px">Mesajı gördüğünde kendine şu soruları sor:</p><div class="error-steps"><div class="error-step"><span class="number">1</span><div><strong>Ne başarısız oldu?</strong><p>Komut ve hata türünü mesajdan ayır.</p></div></div><div class="error-step"><span class="number">2</span><div><strong>Hangi bilgi eksik?</strong><p>Branch durumu, son commit ve remote farkı.</p></div></div><div class="error-step"><span class="number">3</span><div><strong>En risksiz kanıtı topla</strong><p>git status, git branch -vv, git fetch.</p></div></div><div class="error-step"><span class="number">4</span><div><strong>Sonucu doğrula</strong><p>Çözümden sonra test edip push durumuna bak.</p></div></div></div><div class="source-note" style="margin-top:17px"><strong>Kaynak standardı:</strong> Öğretici adımlar resmi araç dokümantasyonuyla karşılaştırılır. Topluluk cevapları örnek olabilir; tek başına doğruluk kanıtı sayılmaz.</div></aside></div><div class="section-label">Sonraki hata konuları</div><div class="github-grid">${[['IDE ve SDK','dotnet SDK bulunamadı','PATH ve yüklenen SDK sürümlerini incele.'],['API ve tarayıcı','CORS hatası','Tarayıcı policy’sini ve response başlıklarını ayır.'],['Unity build','Android build başarısız','İlk gerçek error satırını ve build ortamını bul.']].map((x,i)=>`<article class="practice-tile" data-action="coming-error"><span>YAKINDA · ${['.NET','HTTP','UNITY'][i]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>`}
function conceptsView(){const cards=[...concepts,...expandedConcepts],c=cards.find(x=>x.id===state.conceptOpen);return `${heading('KAVRAM ATÖLYESİ','Adını duydun. Şimdi gerçekten anla.',`${cards.length} kaynaklı kavram · Git’te günlük branch akışından conflict ve geçmişi geri almaya kadar. Önce kısa anlatım, sonra kendi cümlenle açıkla.`)}<label class="concept-search-label" for="conceptSearch">Kavram veya Git komutu ara</label><input id="conceptSearch" class="concept-search" type="search" placeholder="Örn. API, cache, git rebase…" autocomplete="off"><p id="conceptSearchCount" class="concept-search-count" aria-live="polite">${cards.length} kavram</p><div class="concept-grid">${cards.map(x=>`<article class="concept-card" data-concept="${x.id}"><span class="concept-type">${x.type}</span><h3>${x.name}</h3><p>${x.desc}</p><div class="concept-footer"><span>Kaynaklı anlatım</span><span>Öğren →</span></div></article>`).join('')}</div>${c?`<article class="concept-detail"><div class="eyebrow">${c.type}</div><h2>${c.name}</h2><p>${c.body}</p><div class="analogy"><strong>Bir örnekle düşün:</strong> ${c.analogy}</div><div class="source-note" style="margin-top:13px"><strong>Kontrol edilebilir kaynak:</strong> ${link(c.source,c.source.label)}</div><label for="conceptAnswer" class="field-label">Şimdi kendi cümlenle açıkla</label><textarea id="conceptAnswer" class="answer-area" placeholder="Bunu başka bir geliştiriciye şöyle anlatırdım…"></textarea><div class="answer-tools"><button class="mic-button" data-action="mic" data-target="conceptAnswer">🎙 Sesli anlat</button><button class="primary-button" data-action="check-concept">Açıklamamı gözden geçir <span>→</span></button><span class="text-muted">Bu prototipte otomatik yapay zekâ değerlendirmesi yok.</span></div><div id="conceptFeedback"></div></article>`:''}<div class="source-note" style="margin-top:15px"><strong>Bilgi disiplini:</strong> Tanımlar MDN, Git, GitHub, Kubernetes, PostgreSQL ve üretici belgeleri gibi kaynaklara bağlanır. Topluluk yazıları resmi davranış tanımının yerine geçmez.</div>`}
function newsView(){return `${heading('YAZILIM HABERLERİ','Gündemi takip et, etkisini anla','AI modelleri, geliştirici araçları ve altyapı gelişmeleri. Kaynağa git veya kısa özeti aç.',`<span class="day-pill">Kontrol: 5 Ekim 2026</span>`)}<div class="source-note"><strong>Güvenilirlik kuralı:</strong> Bu akıştaki kartlar ilk sürüm için elle seçilmiş kaynaklı örneklerdir, canlı haber akışı değildir. Yayın tarihi kaynak sayfasından alınmıştır. Her kartta asıl kaynağa gidebilirsin.</div><div class="news-list">${news.map((n,i)=>`<article class="news-card"><div class="news-card-top"><span class="source-badge">${n.kind}</span><span>${n.date}</span><span>·</span><span>${n.tag}</span></div><h3>${n.title}</h3><p>${n.body}</p><div class="news-summary ${state.newsSummaries[i]?'open':''}" id="summary-${i}"><strong>Kısa özet:</strong> ${n.summary}</div><div class="news-actions"><button data-action="summary" data-index="${i}">${state.newsSummaries[i]?'Özeti kapat':'Haberi özetle'}</button>${link(n.source,`Asıl kaynak: ${n.source.label}`)}</div></article>`).join('')}</div><div class="section-label">Kaynak yaklaşımı</div><div class="two-col"><section class="panel panel-pad"><h2 class="panel-title">Resmi kaynaklar</h2><p class="quiz-context" style="margin:8px 0 0">Sürüm, API davranışı ve yeni model özellikleri için önce ürün dokümantasyonu, changelog veya resmi proje blogu. Üçüncü taraf açıklamalar, kaynağa göreli yorumlarıyla sunulur.</p></section><section class="panel panel-pad"><h2 class="panel-title">Topluluk kaynakları</h2><p class="quiz-context" style="margin:8px 0 0">Medium ve Stack Overflow fikir, deneyim ve hata örnekleri bulmaya yardım eder. İçerikler yayımlanmadan önce birincil kaynaklarla doğrulanmalı; kişisel görüş, resmi bilgi gibi işaretlenmemeli.</p></section></div>`}
function githubView(){return `${heading('GITHUB PRATİĞİ','Ekipte kodu nasıl güvenle teslim edersin?','Commit ve branch’ten GitHub Actions’a: kavramı oku, senaryoda uygula, sonra kendi repo akışına taşı.')}<div class="source-note"><strong>Kaynak:</strong> Git’in resmi dokümantasyonu ve GitHub Docs/Changelog. Workflow davranışları değişebileceği için güncel sözdizimi kaynak sayfasından kontrol edilir.</div><div class="github-grid">${[['01 · GIT','Branch ve commit','Değişiklikleri küçük, anlamlı parçalara ayır.'],['02 · COLLABORATION','Pull request','Değişikliği incelet, tartış ve test sonuçlarını kontrol et.'],['03 · HATA','Merge conflict','İki değişiklik aynı satırları etkileyince kanıtla çöz.'],['04 · AUTOMATION','GitHub Actions','Workflow YAML ile build ve test adımlarını otomatikleştir.'],['05 · SECURITY','GITHUB_TOKEN','Workflow’a gereken en az izinleri ver.'],['06 · DEBUG','Kırmızı workflow','Başarısız job, step, log ve artefact’ı sırasıyla incele.']].map(x=>`<article class="practice-tile" data-action="${x[0].includes('HATA')?'goto-errors':'github-lesson'}"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><div class="section-label">Örnek: Actions güncellemesi</div><article class="news-card"><div class="news-card-top"><span class="source-badge">Resmi changelog</span><span>3 Eylül 2026</span></div><h3>Runner sürüm sonunu izleme ve vulnerability-alerts token izni</h3><p>Bu changelog kaydı, runner sürüm deprecations bilgisi için API ve GITHUB_TOKEN'a yeni salt okunur izin eklenmesini anlatıyor.</p><div class="news-actions">${link(sources.github,'GitHub Changelog kaynağı')}</div></article>`}
function sourceConceptsView(){
 const bank=window.realdevContentBank||{cards:[],sources:{}},en=window.realdevLocale==='en';
 const say=v=>typeof v==='string'?v:(v?.[en?'en':'tr']||v?.tr||'');
 const cards=[...concepts,...expandedConcepts,...bank.cards.map(x=>({...x,sourceMeta:bank.sources[x.source],source:{label:bank.sources[x.source]?.name||x.source,url:bank.sources[x.source]?.url||'#'}}))];
 const c=cards.find(x=>x.id===state.conceptOpen), title=en?'CONCEPT WORKSHOP':'KAVRAM ATÖLYESİ';
 let html=heading(title,en?'Understand the term, then explain it.':'Kavramı anla, sonra kendin açıkla.',en?cards.length+' searchable cards across code, teamwork, data, operations, AI, mobile and games.':'Kod, ekip, veri, operasyon, yapay zekâ, mobil ve oyun geliştirmede '+cards.length+' aranabilir kavram kartı.');
 html+='<label class="concept-search-label" for="conceptSearch">'+(en?'Search concepts':'Kavramlarda ara')+'</label><input id="conceptSearch" class="concept-search" type="search" placeholder="'+(en?'e.g. API, React state, pooling…':'Örn. API, React state, pooling…')+'" autocomplete="off"><p id="conceptSearchCount" class="concept-search-count" aria-live="polite">'+cards.length+' '+(en?'concepts':'kavram')+'</p><div class="concept-grid">';
 html+=cards.map(x=>'<article class="concept-card" data-concept="'+esc(x.id)+'"><span class="concept-type">'+esc(say(x.type))+'</span><h3>'+esc(say(x.name))+'</h3><p>'+esc(say(x.desc))+'</p><div class="concept-footer"><span>'+(en?'Source linked':'Kaynak bağlı')+'</span><span>'+(en?'Learn →':'Öğren →')+'</span></div></article>').join('');
 html+='</div>';
 if(c){
  html+='<article class="concept-detail"><div class="eyebrow">'+esc(say(c.type))+'</div><h2>'+esc(say(c.name))+'</h2><div class="concept-body">'+esc(say(c.body)).replace(/\n/g,'<br>')+'</div><div class="analogy"><strong>'+(en?'Example:':'Bir örnekle düşün:')+'</strong> '+esc(say(c.analogy))+'</div><div class="source-note" style="margin-top:13px"><strong>'+(en?'Check the source:':'Kaynağı kontrol et:')+'</strong> '+link(c.source,c.source.label);
  if(c.sourceMeta)html+='<br><strong>'+(en?'License:':'Lisans:')+'</strong> '+esc(c.sourceMeta.license)+' <a href="'+esc(c.sourceMeta.licenseUrl)+'" target="_blank" rel="noopener noreferrer">'+(en?'License details':'Lisans ayrıntısı')+' ↗</a><br><strong>'+(en?'How we use it:':'Kullanım biçimi:')+'</strong> '+esc(c.sourceMeta.use);
  html+='</div><label for="conceptAnswer" class="field-label">'+(en?'Explain it in your own words':'Şimdi kendi cümlenle açıkla')+'</label><textarea id="conceptAnswer" class="answer-area" placeholder="'+(en?'I would explain this to another developer as…':'Bunu başka bir geliştiriciye şöyle anlatırdım…')+'"></textarea><div class="answer-tools"><button class="mic-button" data-action="mic" data-target="conceptAnswer">🎙 '+(en?'Explain aloud':'Sesli anlat')+'</button><button class="primary-button" data-action="check-concept">'+(en?'Review my explanation':'Açıklamamı gözden geçir')+' →</button><span class="text-muted">'+(en?'No automatic accuracy score is given.':'Açıklamaya otomatik doğruluk puanı verilmiyor.')+'</span></div><div id="conceptFeedback"></div></article>';
 }
 const sources=Object.values(bank.sources);
 html+='<details class="source-note" style="margin-top:15px"><summary><strong>'+(en?'Sources and reuse notes':'Kaynaklar ve yeniden kullanım notları')+'</strong> · '+sources.length+'</summary><div class="github-grid" style="margin-top:12px">';
 html+=sources.map(s=>'<article class="practice-tile"><h3>'+link(s,s.name)+'</h3><p>'+esc(s.license)+'</p><p>'+(en?'Use:':'Kullanım:')+' '+esc(s.use)+'</p>'+link({label:en?'License or terms':'Lisans / koşullar',url:s.licenseUrl},en?'License or terms':'Lisans / koşullar')+'</article>').join('');
 html+='</div><p>'+(en?'Cards are original RealDev explanations based on linked references. External question wording is not copied. Recheck individual asset notices and source versions before reuse.':'Kartlar, bağlantılı kaynaklara dayanan özgün RealDev anlatımlarıdır. Harici soru metinleri kopyalanmadı. İçerikleri yeniden kullanmadan önce dosya bazında lisans istisnalarını ve kaynak sürümlerini kontrol edin.')+'</p></details>';
 return html;
}
const renderers={today,quiz:quizView,map:mapView,errors:errorsView,concepts:sourceConceptsView,news:newsView,github:githubView,landing:publicLanding,demoQuiz:guestQuizView,demoConcepts:guestConceptsView};
const routePaths={calendar:'/calendar',today:'/today',quiz:'/quiz',map:'/map',route:'/route',history:'/history',topics:'/topics',notes:'/notes',library:'/library',lab:'/lab',interview:'/interview',errors:'/errors',concepts:'/concepts',news:'/news',github:'/github',codehistory:'/code-history',review:'/review',advanced:'/advanced',account:'/account',landing:'/',demoQuiz:'/demo/questions',demoConcepts:'/demo/concepts'};const routeNames=new Set(Object.keys(routePaths));const routeFromHash=()=>{const value=decodeURIComponent(location.hash.slice(1));return routeNames.has(value)?value:'today'};const normalizePath=()=>decodeURIComponent(location.pathname).replace(/\/+$/,'')||'/';const routeFromLocation=()=>{const path=normalizePath();if(path==='/'){if(location.hash){const legacy=routeFromHash();if(legacy!=='today')return legacy;}return 'today';}return Object.entries(routePaths).find(([view,target])=>target===path&&view!=='landing')?.[0]||'today'};const requestedView=document.body.dataset.realdevInitialView||routeFromLocation();let currentView=signedIn?requestedView:(['demoQuiz','demoConcepts'].includes(requestedView)?requestedView:'today');if(location.hash)history.replaceState(null,'',routePaths[currentView]||'/');function updateDocumentSeo(view=currentView){const path=normalizePath();const pages={calendar:['Study calendar · RealDeveloper','Your private active study minutes and monthly learning calendar.'],today:['Today · RealDeveloper','Your private daily developer practice and progress summary.'],quiz:['Skill assessment · RealDeveloper','Assess your software development skills with practical questions and evidence-based feedback.'],map:['Skill map · RealDeveloper','Review your developer skill evidence, practice areas and next learning steps.'],route:['Learning route · RealDeveloper','Follow a personal developer learning route built from your practice evidence.'],history:['Answer history · RealDeveloper','Review your saved answers and revisit questions from your account.'],topics:['Topic search · RealDeveloper','Search software topics and find related practice in your account.'],notes:['My notes · RealDeveloper','Review your private study notes and recorded learning gaps.'],library:['Question library · RealDeveloper','Revisit questions saved to your personal developer practice library.'],lab:['Code lab · RealDeveloper','Write and run supported practice code in an isolated learning environment.'],interview:['Interview and project practice · RealDeveloper','Practice technical interviews, staged projects, debugging and code review.'],errors:['Error lab · RealDeveloper','Practice diagnosing Git, API, IDE, .NET, Unity and deployment errors.'],concepts:['Software concepts · RealDeveloper','Study software engineering concepts with sourced explanations and examples.'],news:['Software development news · RealDeveloper','Follow software development updates with dates and links to their original sources.'],github:['GitHub practice · RealDeveloper','Practice Git, pull requests, collaboration and GitHub Actions workflows.'],codehistory:['Code history · RealDeveloper','Review code submissions and test results saved to your account.'],review:['Review a question · RealDeveloper','Return to questions saved for review and study their explanations.'],advanced:['Advanced practice · RealDeveloper','Continue advanced software engineering projects and technical practice.'],account:['Account and data · RealDeveloper','Manage your RealDeveloper profile, learning data and account settings.'],demoQuiz:['Sample developer questions · RealDeveloper','Try sample programming, debugging and software engineering questions in a temporary, unsaved preview.'],demoConcepts:['Software concept glossary · RealDeveloper','Browse ten sourced software engineering concept cards with references to original documentation.']};const data=pages[view]||pages.today;document.title=data[0];const set=(selector,value,attribute='content')=>{const el=document.querySelector(selector);if(el)el.setAttribute(attribute,value);};set('meta[name="description"]',data[1]);const indexable=path==='/'||path==='/demo/questions'||path==='/demo/concepts';set('meta[name="robots"]',indexable?'index, follow':'noindex, nofollow');set('meta[property="og:title"]',data[0]);set('meta[property="og:description"]',data[1]);set('meta[property="og:url"]',location.origin+path);set('link[rel="canonical"]',location.origin+path,'href');}function syncViewFromUrl(){const next=routeFromLocation();if(state.view===next){updateDocumentSeo(next);return;}currentView=next;state.quizMode=false;updateDocumentSeo(next);render();}Object.defineProperty(state,'view',{configurable:true,enumerable:true,get:()=>currentView,set:value=>{currentView=routeNames.has(value)?value:'today';const target=routePaths[currentView]||'/today';if(location.pathname!==target||location.hash)history.pushState(null,'',target);updateDocumentSeo(currentView);}});window.addEventListener('popstate',syncViewFromUrl);window.addEventListener('hashchange',syncViewFromUrl);updateDocumentSeo(currentView);function render(){const view=state.view;const guestView=view==='demoQuiz'?guestQuizView:view==='demoConcepts'?guestConceptsView:publicLanding;if(!signedIn){document.body.classList.add('guest-mode');root.innerHTML=guestView();document.getElementById('crumbCurrent').textContent=bilingual('Açık önizleme','Public preview');document.querySelectorAll('.nav-item').forEach(b=>b.classList.remove('active'));return;}document.body.classList.remove('guest-mode');const privateView=view==='landing'||view==='demoQuiz'||view==='demoConcepts'?'today':view;root.innerHTML=(renderers[privateView]||today)();const names={calendar:window.realdevLocale==='en'?'Study calendar':'Çalışma takvimim',advanced:window.realdevLocale==='en'?'Advanced practice':'İleri eğitim',interview:window.realdevLocale==='en'?'Interviews and projects':'Mülakat ve projeler',today:'Bugün',quiz:'Beceri taraması',map:'Beceri haritam',errors:'Hata laboratuvarı',concepts:'Kavramlar',news:'Yazılım haberleri',github:'GitHub pratiği',route:'Çalışma rotam',history:'Cevap geçmişim',topics:'Konu ara',notes:'Notlarım',account:'Hesabım',lab:'Kod alanı',codehistory:'Kod geçmişim',library:'Kütüphanem',review:'Soruyu tekrar incele'};document.getElementById('crumbCurrent').textContent=names[privateView]||'Bugün';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===privateView||(privateView==='quiz'&&b.dataset.view==='today')))}
window.realdevRender=render;
function go(view){if(!signedIn&&!['landing','demoQuiz','demoConcepts'].includes(view)){location.assign('/auth.html#/sign-in');return;}state.view=view;state.quizMode=false;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo(0,0)}
function setSignedInUser(user){const wasSignedIn=signedIn;signedIn=Boolean(user?.emailVerified);window.realdevAuthenticated=signedIn;document.body.classList.toggle('guest-mode',!signedIn);if(signedIn){loadProgress();if(!wasSignedIn&&['landing','demoQuiz','demoConcepts'].includes(state.view))state.view='today';}else if(wasSignedIn){state.completed=0;state.errorSolved=false;state.answerText='';state.selected=null;state.answered=false;}render();}
window.realdevAuthStateChanged=setSignedInUser;
window.realdevSessionReady?.then(setSignedInUser);
document.addEventListener('click',event=>{if(signedIn)return;const publicView=event.target.closest('[data-public-view]');if(publicView){event.preventDefault();event.stopImmediatePropagation();const view=publicView.dataset.publicView;if(view==='demoQuiz'){guestQuizIndex=0;guestSelected=null;guestAnswered=false;}if(view==='landing')guestConceptOpen=null;state.view=view;render();window.scrollTo(0,0);return;}const choice=event.target.closest('[data-guest-choice]');if(choice&&state.view==='demoQuiz'&&!guestAnswered){event.preventDefault();event.stopImmediatePropagation();guestSelected=Number(choice.dataset.guestChoice);guestAnswered=true;render();return;}const next=event.target.closest('[data-guest-action="next"]');if(next){event.preventDefault();event.stopImmediatePropagation();guestQuizIndex++;guestSelected=null;guestAnswered=false;render();window.scrollTo(0,0);return;}const concept=event.target.closest('[data-guest-concept]');if(concept){event.preventDefault();event.stopImmediatePropagation();guestConceptOpen=concept.dataset.guestConcept;render();document.querySelector('.concept-detail')?.scrollIntoView({behavior:'smooth',block:'center'});return;}const gated=event.target.closest('[data-view],[data-action],[data-rd],[data-advanced],#profileOpen,#profileOpenTop,#reminderButton');if(gated){event.preventDefault();event.stopImmediatePropagation();location.assign('/auth.html#/sign-in');}},true);
document.addEventListener('input',e=>{if(e.target.id!=='conceptSearch')return;const terms=e.target.value.toLocaleLowerCase('tr-TR').trim().split(/\s+/).filter(Boolean);let visible=0;document.querySelectorAll('.concept-card').forEach(card=>{const text=card.textContent.toLocaleLowerCase('tr-TR');const show=terms.every(term=>text.includes(term));card.hidden=!show;if(show)visible++});const count=document.getElementById('conceptSearchCount');if(count)count.textContent=`${visible} kavram`;});
document.addEventListener('click',e=>{const viewButton=e.target.closest('[data-view]');if(viewButton){go(viewButton.dataset.view);return}const choice=e.target.closest('[data-choice]');if(choice&&!state.answered){state.selected=Number(choice.dataset.choice);state.answered=true;if(state.selected===quiz[state.quizIndex].answer)state.completed++;save();render();return}const concept=e.target.closest('[data-concept]');if(concept){state.conceptOpen=concept.dataset.concept;render();document.querySelector('.concept-detail')?.scrollIntoView({behavior:'smooth',block:'center'});return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'start-quiz':state.view='quiz';state.quizMode=true;state.quizIndex=0;state.selected=null;state.answered=false;render();break;case'next-quiz':state.quizIndex++;state.selected=null;state.answered=false;if(state.quizIndex>=quiz.length){state.view='quiz';state.quizMode=true}render();break;case'dont-know':state.selected=-1;state.answered=true;render();break;case'reset-quiz':state.quizIndex=0;state.selected=null;state.answered=false;render();break;case'hint':state.errorHint++;render();break;case'check-error':state.answerText=document.getElementById('errorAnswer').value.trim();if(!state.answerText){toast('Önce teşhis düşünceni yaz veya sesli anlat.');break}state.errorSolved=true;save();render();break;case'mic':startSpeech(a.dataset.target||'errorAnswer');break;case'check-concept':conceptFeedback();break;case'summary':{const i=Number(a.dataset.index);state.newsSummaries[i]=!state.newsSummaries[i];render();break}case'coming-error':toast('Bu senaryo ilk sürümde yakında eklenecek.');break;case'github-lesson':toast('Bu çalışma kartı sıradaki geliştirme adımında.');break;case'goto-errors':go('errors');break}});
function startSpeech(targetId){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('Bu tarayıcı sesli yazmayı desteklemiyor. Yazılı yanıtı kullanabilirsin.');return}const r=new Speech();r.lang=window.realdevLocale==='en'?'en-US':'tr-TR';r.interimResults=false;r.onresult=ev=>{const el=document.getElementById(targetId);if(el){el.value+=(el.value?' ':'')+ev.results[0][0].transcript;state.answerText=el.value}};r.onerror=()=>toast('Ses tanınamadı. İstersen yazılı yanıt verebilirsin.');r.start();toast(window.realdevLocale==='en'?'Listening… explain in English.':'Dinliyorum… Türkçe açıklamanı yap.');}
function conceptFeedback(){const input=document.getElementById('conceptAnswer')?.value.trim();const box=document.getElementById('conceptFeedback');if(!input){box.innerHTML='<div class="result-box warning">Önce kendi cümlenle kısa bir açıklama yaz.</div>';return}const words=input.split(/\s+/).length;box.innerHTML=`<div class="result-box ${words<12?'warning':''}"><h4>${words<12?'Biraz daha açmayı dene.':'İyi bir başlangıç.'}</h4>${words<12?'Açıklamana ne işe yaradığını ve nerede kullanıldığını ekle.':'Açıklamanı kendin oluşturdun. Şimdi kaynak anlatımıyla karşılaştır: hangi noktayı eklerdin?'} Otomatik teknik doğruluk puanı vermiyoruz; bu prototip yanıtını sunucuya göndermiyor.</div>`;}
document.getElementById('menuButton').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
function profileKey(name){const uid=window.realdevCurrentUser?.uid;return signedIn&&uid?`realdev-profile:${uid}:${name}`:null}
function profile(){if(!signedIn){location.assign('/auth.html#/sign-in');return}const goal=document.getElementById('dailyGoal');goal.value=localStorage.getItem(profileKey('daily-goal'))||'15 dakika';const selected=JSON.parse(localStorage.getItem(profileKey('goals'))||'["Full stack","Oyun geliştirme"]');document.querySelectorAll('#goalOptions input').forEach(input=>input.checked=selected.includes(input.value));document.getElementById('profileDialog').showModal()};document.getElementById('profileOpen').addEventListener('click',profile);document.getElementById('profileOpenTop').addEventListener('click',profile);document.getElementById('saveProfile').addEventListener('click',()=>{if(!signedIn){location.assign('/auth.html#/sign-in');return}const goals=[...document.querySelectorAll('#goalOptions input:checked')].map(input=>input.value);if(!goals.length){toast('En az bir öğrenme hedefi seç.');return}localStorage.setItem(profileKey('daily-goal'),document.getElementById('dailyGoal').value);localStorage.setItem(profileKey('goals'),JSON.stringify(goals));document.getElementById('goalSubtitle').textContent=goals.join(' · ');document.getElementById('profileDialog').close();toast('Hedeflerin ve günlük süren hesabında saklandı.')});document.getElementById('reminderButton').addEventListener('click',()=>{if(!signedIn){location.assign('/auth.html#/sign-in');return}window.realdevReminders?.()});
render();


